def beam_search(step, bos, L, B):
    beams = [([bos], 0.0)]
    for _ in range(L):
        cand = []
        for seq, sc in beams:
            lp = step(seq)
            for t in range(len(lp)):
                cand.append((seq + [t], sc + lp[t]))
        cand.sort(key=lambda c: -c[1])
        beams = cand[:B]
    return beams

from collections import Counter

def merge(s, a, b):
    out, i = [], 0
    while i < len(s):
        if i < len(s) - 1 and (s[i], s[i + 1]) == (a, b):
            out.append(a + b)
            i += 2
        else:
            out.append(s[i])
            i += 1
    return out

def bpe_train(words, k):
    seqs, merges = [list(w) for w in words], []
    for _ in range(k):
        cnt = Counter()
        for s in seqs:
            cnt.update(zip(s, s[1:]))
        if not cnt:
            break
        a, b = min(cnt, key=lambda p: (-cnt[p], p))
        seqs = [merge(s, a, b) for s in seqs]
        merges.append((a, b))
    return merges

def bpe_encode(word, merges):
    s = list(word)
    for a, b in merges:
        s = merge(s, a, b)
    return s

