def early_stop(losses, patience, min_delta=0.0):
    best, best_epoch, wait = float("inf"), -1, 0
    for epoch, loss in enumerate(losses):
        if loss < best - min_delta:
            best, best_epoch, wait = loss, epoch, 0
        else:
            wait += 1
            if wait >= patience:
                return epoch, best_epoch, best
    return len(losses) - 1, best_epoch, best

