import numpy as np

def q_learning(nxt, rew, done, n_ep=3000, alpha=0.5, gamma=0.9,
               eps=0.3, seed=0):
    rng = np.random.default_rng(seed)
    S, A = nxt.shape
    Q = np.zeros((S, A))
    for _ in range(n_ep):
        s = rng.integers(S)
        for _ in range(100):
            if done[s]:
                break
            if rng.random() < eps:
                a = rng.integers(A)
            else:
                a = Q[s].argmax()
            s2 = nxt[s, a]
            target = rew[s, a] + gamma * Q[s2].max()
            Q[s, a] += alpha * (target - Q[s, a])
            s = s2
    return Q

import numpy as np

def gini(y):
    p = np.bincount(y, minlength=2) / len(y)
    return 1 - p @ p

def grow(X, y, depth, m, rng):
    leaf = np.bincount(y, minlength=2).argmax()
    if depth == 0 or gini(y) == 0:
        return leaf
    best = (gini(y), None, None)
    for j in rng.choice(X.shape[1], m, replace=False):
        for t in np.unique(X[:, j])[:-1]:
            k = X[:, j] <= t
            s = k.mean() * gini(y[k]) + (1 - k.mean()) * gini(y[~k])
            if s < best[0]:
                best = (s, j, t)
    if best[1] is None:
        return leaf
    _, j, t = best
    k = X[:, j] <= t
    l = grow(X[k], y[k], depth - 1, m, rng)
    return (j, t, l, grow(X[~k], y[~k], depth - 1, m, rng))

